@props([
    'stepValue' => null,
])

@aware([
    'defaultValue' => null,
    'stepperId' => null,
    'orientation' => 'horizontal',
])

@php
    $stepValue = $stepValue ?? $attributes->get('value');
    $attributes = $attributes->except('value');

    if (! filled($stepValue)) {
        throw new \InvalidArgumentException('The stepper content component requires a [value] attribute.');
    }

    $isSelected = filled($defaultValue) && (string) $stepValue === (string) $defaultValue;
    $panelId = $attributes->get('id')
        ?? (filled($stepperId) ? $stepperId.'-panel-'.$stepValue : null);
    $triggerId = filled($stepperId) ? $stepperId.'-trigger-'.$stepValue : null;
    $isVertical = $orientation === 'vertical';
@endphp

<div {{
    $attributes->except(['id'])->class([
        'stepper__content',
        'min-w-0 flex-1 text-sm text-zinc-700 focus-visible:outline-none dark:text-zinc-300',
        ! $isSelected ? 'hidden' : null,
        $isVertical ? null : 'w-full',
    ])->merge([
        'id' => $panelId,
        'role' => 'region',
        'aria-labelledby' => $triggerId,
        'data-stepper-content' => true,
        'data-value' => (string) $stepValue,
        'data-state' => $isSelected ? 'active' : 'inactive',
        'tabindex' => '0',
        'hidden' => $isSelected ? null : true,
    ])
}}>
    {{ $slot }}
</div>

@props([
    'defaultValue' => null,
    'orientation' => 'horizontal',
    'linear' => true,
    'stepperId' => null,
])

@php
    $stepperId = filled($stepperId) ? $stepperId : 'stepper-'.str_replace('.', '', uniqid('', true));
    $isVertical = $orientation === 'vertical';
@endphp

<div {{
    $attributes->class([
        'stepper',
        'flex w-full',
        $isVertical ? 'flex-row gap-8' : 'flex-col gap-6',
    ])->merge([
        'data-stepper' => true,
        'data-stepper-id' => $stepperId,
        'data-orientation' => $isVertical ? 'vertical' : 'horizontal',
        'data-linear' => $linear ? 'true' : 'false',
        'data-active' => filled($defaultValue) ? (string) $defaultValue : null,
    ])
}}>
    {{ $slot }}
</div>

@aware([
    'defaultValue' => null,
    'value' => null,
    'step' => null,
    'completed' => null,
])

@php
    $isCurrent = filled($defaultValue) && filled($value) && (string) $value === (string) $defaultValue;
    $isCompleted = $completed === true;
    $label = filled($step) ? (string) $step : (filled($value) ? (string) $value : '');
@endphp

<span {{
    $attributes->class([
        'stepper__indicator',
        'relative z-10 flex size-8 shrink-0 items-center justify-center rounded-full border text-sm font-medium transition-colors',
        'border-zinc-200 bg-white text-zinc-600',
        'group-data-[state=active]/step:border-zinc-900 group-data-[state=active]/step:bg-zinc-900 group-data-[state=active]/step:text-zinc-50',
        'group-data-[state=completed]/step:border-zinc-900 group-data-[state=completed]/step:bg-zinc-900 group-data-[state=completed]/step:text-zinc-50',
        'dark:border-zinc-700 dark:bg-zinc-950 dark:text-zinc-300',
        'dark:group-data-[state=active]/step:border-zinc-100 dark:group-data-[state=active]/step:bg-zinc-100 dark:group-data-[state=active]/step:text-zinc-900',
        'dark:group-data-[state=completed]/step:border-zinc-100 dark:group-data-[state=completed]/step:bg-zinc-100 dark:group-data-[state=completed]/step:text-zinc-900',
    ])->merge([
        'data-stepper-indicator' => true,
        'aria-hidden' => 'true',
    ])
}}>
    @if ($slot->isNotEmpty())
        {{ $slot }}
    @else
        <span
            @class([
                'stepper__indicator-number',
                $isCompleted ? 'hidden' : 'inline-flex',
                'group-data-[state=completed]/step:hidden',
            ])
        >{{ $label }}</span>
        <span @class([
            'stepper__indicator-check',
            $isCompleted ? 'inline-flex' : 'hidden',
            'group-data-[state=completed]/step:inline-flex group-data-[state=active]/step:hidden group-data-[state=inactive]/step:hidden',
        ])>
            <x-ui::icon name="check" class="size-4" />
        </span>
    @endif
</span>

@props([
    'value',
    'step' => null,
    'completed' => null,
    'disabled' => false,
])

@aware([
    'defaultValue' => null,
    'orientation' => 'horizontal',
    'stepperId' => null,
])

@php
    $isVertical = $orientation === 'vertical';
    $isDisabled = (bool) $disabled;
    $isCurrent = filled($defaultValue) && (string) $value === (string) $defaultValue;

    $state = match (true) {
        $isCurrent => 'active',
        $completed === true => 'completed',
        default => 'inactive',
    };

    $triggerId = $attributes->get('id')
        ?? (filled($stepperId) ? $stepperId.'-trigger-'.$value : null);
    $panelId = filled($stepperId) ? $stepperId.'-panel-'.$value : null;
@endphp

<li {{
    $attributes->except(['id'])->class([
        'stepper__item',
        'group/step relative flex',
        $isVertical ? 'w-full flex-col' : 'flex-1 flex-col items-center',
        $isDisabled ? 'pointer-events-none opacity-50' : null,
    ])->merge([
        'data-stepper-item' => true,
        'data-value' => (string) $value,
        'data-step' => filled($step) ? (string) $step : null,
        'data-state' => $state,
        'data-disabled' => $isDisabled ? 'true' : null,
        'aria-current' => $isCurrent ? 'step' : null,
    ])
}}>
    {{ $slot }}
</li>

@aware([
    'orientation' => 'horizontal',
])

@php
    $isVertical = $orientation === 'vertical';
@endphp

<div
    {{
        $attributes->class([
            'stepper__separator',
            'bg-zinc-200 dark:bg-zinc-800',
            'group-data-[state=completed]/step:bg-zinc-900 dark:group-data-[state=completed]/step:bg-zinc-100',
            $isVertical
            ? 'ms-4 mt-2 hidden h-6 w-px group-[:not(:last-child)]/step:block'
            : 'absolute start-[calc(50%+1.25rem)] top-4 hidden h-px w-[calc(100%-2.5rem)] group-[:not(:last-child)]/step:block',
        ])->merge([
            'data-stepper-separator' => true,
            'aria-hidden' => 'true',
            'role' => 'none',
        ])
    }}
></div>

@aware([
    'defaultValue' => null,
    'orientation' => 'horizontal',
    'stepperId' => null,
    'value' => null,
    'disabled' => false,
])

@php
    $isVertical = $orientation === 'vertical';
    $isDisabled = (bool) $disabled;
    $isCurrent = filled($defaultValue) && filled($value) && (string) $value === (string) $defaultValue;

    $triggerId = $attributes->get('id')
        ?? (filled($stepperId) && filled($value) ? $stepperId.'-trigger-'.$value : null);
    $panelId = filled($stepperId) && filled($value) ? $stepperId.'-panel-'.$value : null;
@endphp

<button
    type="button"
    {{
        $attributes->except(['id'])->class([
            'stepper__trigger',
            'inline-flex items-center gap-3 rounded-lg text-left transition-colors',
            'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-zinc-950/10 dark:focus-visible:ring-zinc-300/20',
            $isVertical ? 'w-full' : 'flex-col text-center sm:flex-row sm:text-left',
            $isDisabled ? 'cursor-not-allowed' : 'cursor-pointer',
        ])->merge([
            'id' => $triggerId,
            'data-stepper-trigger' => true,
            'data-value' => filled($value) ? (string) $value : null,
            'aria-controls' => $panelId,
            'aria-current' => $isCurrent ? 'step' : null,
            'disabled' => $isDisabled ? true : null,
            'tabindex' => $isCurrent ? '0' : '-1',
        ])
    }}
>
    {{ $slot }}
</button>

/**
 * Stencil — accessible stepper / wizard steps (vanilla JS, no Alpine).
 */

const STEPPER_SELECTOR = '[data-stepper]';
const ITEM_SELECTOR = '[data-stepper-item]';
const TRIGGER_SELECTOR = '[data-stepper-trigger]';
const CONTENT_SELECTOR = '[data-stepper-content]';
const PREVIOUS_SELECTOR = '[data-stepper-previous]';
const NEXT_SELECTOR = '[data-stepper-next]';
const initialized = new WeakSet();

/**
 * @param {ParentNode} root
 */
export function initSteppers(root = document) {
    root.querySelectorAll(STEPPER_SELECTOR).forEach((element) => {
        if (!(element instanceof HTMLElement)) {
            return;
        }

        if (initialized.has(element)) {
            return;
        }

        initialized.add(element);
        bindStepper(element);
    });
}

/**
 * @param {HTMLElement} root
 */
function bindStepper(root) {
    const linear = root.dataset.linear !== 'false';

    const items = () =>
        Array.from(root.querySelectorAll(ITEM_SELECTOR)).filter(
            (node) => node instanceof HTMLElement && node.dataset.disabled !== 'true',
        );

    const contents = () =>
        Array.from(root.querySelectorAll(CONTENT_SELECTOR)).filter(
            (node) => node instanceof HTMLElement,
        );

    const triggers = () =>
        Array.from(root.querySelectorAll(TRIGGER_SELECTOR)).filter(
            (node) => node instanceof HTMLButtonElement && !node.disabled,
        );

    /**
     * @param {string} value
     */
    const activate = (value) => {
        const enabledItems = items();
        const index = enabledItems.findIndex((item) => item.dataset.value === value);

        if (index < 0) {
            return;
        }

        root.dataset.active = value;

        enabledItems.forEach((item, itemIndex) => {
            let state = 'inactive';

            if (itemIndex < index) {
                state = 'completed';
            } else if (itemIndex === index) {
                state = 'active';
            }

            item.dataset.state = state;
            item.setAttribute('aria-current', state === 'active' ? 'step' : 'false');

            if (item.getAttribute('aria-current') === 'false') {
                item.removeAttribute('aria-current');
            }

            const trigger = item.querySelector(TRIGGER_SELECTOR);

            if (trigger instanceof HTMLButtonElement) {
                trigger.tabIndex = state === 'active' ? 0 : -1;
                trigger.setAttribute('aria-current', state === 'active' ? 'step' : 'false');

                if (trigger.getAttribute('aria-current') === 'false') {
                    trigger.removeAttribute('aria-current');
                }
            }
        });

        // Also sync disabled items that were filtered out of navigation.
        root.querySelectorAll(ITEM_SELECTOR).forEach((item) => {
            if (!(item instanceof HTMLElement) || item.dataset.disabled !== 'true') {
                return;
            }

            if (item.dataset.state === 'active') {
                item.dataset.state = 'inactive';
            }
        });

        contents().forEach((panel) => {
            const selected = panel.dataset.value === value;
            panel.dataset.state = selected ? 'active' : 'inactive';
            panel.hidden = !selected;
            panel.classList.toggle('hidden', !selected);
        });

        const previous = root.querySelector(PREVIOUS_SELECTOR);
        const next = root.querySelector(NEXT_SELECTOR);

        if (previous instanceof HTMLButtonElement) {
            previous.disabled = index <= 0;
            previous.toggleAttribute('disabled', index <= 0);
            previous.setAttribute('aria-disabled', index <= 0 ? 'true' : 'false');
        }

        if (next instanceof HTMLButtonElement) {
            const atEnd = index >= enabledItems.length - 1;
            next.disabled = atEnd;
            next.toggleAttribute('disabled', atEnd);
            next.setAttribute('aria-disabled', atEnd ? 'true' : 'false');
        }

        root.dispatchEvent(
            new CustomEvent('stencil:stepper:change', {
                bubbles: true,
                detail: { value, index },
            }),
        );
    };

    /**
     * @param {number} delta
     */
    const move = (delta) => {
        const enabledItems = items();
        const currentValue = root.dataset.active;
        const currentIndex = enabledItems.findIndex((item) => item.dataset.value === currentValue);
        const nextIndex = currentIndex + delta;

        if (nextIndex < 0 || nextIndex >= enabledItems.length) {
            return;
        }

        const nextValue = enabledItems[nextIndex]?.dataset.value;

        if (typeof nextValue === 'string') {
            activate(nextValue);
            const trigger = enabledItems[nextIndex]?.querySelector(TRIGGER_SELECTOR);

            if (trigger instanceof HTMLButtonElement) {
                trigger.focus();
            }
        }
    };

    const initial =
        root.dataset.active ||
        items().find((item) => item.dataset.state === 'active')?.dataset.value ||
        items()[0]?.dataset.value;

    if (typeof initial === 'string' && initial !== '') {
        activate(initial);
    }

    root.addEventListener('click', (event) => {
        const target = event.target instanceof Element ? event.target : null;

        if (!target) {
            return;
        }

        const previous = target.closest(PREVIOUS_SELECTOR);

        if (previous instanceof HTMLElement && root.contains(previous)) {
            event.preventDefault();
            move(-1);

            return;
        }

        const next = target.closest(NEXT_SELECTOR);

        if (next instanceof HTMLElement && root.contains(next)) {
            event.preventDefault();
            move(1);

            return;
        }

        const trigger =
            target.closest(TRIGGER_SELECTOR) instanceof HTMLButtonElement
                ? target.closest(TRIGGER_SELECTOR)
                : null;

        if (
            !(trigger instanceof HTMLButtonElement) ||
            !root.contains(trigger) ||
            trigger.disabled
        ) {
            return;
        }

        const value = trigger.dataset.value;

        if (typeof value !== 'string') {
            return;
        }

        const enabledItems = items();
        const targetIndex = enabledItems.findIndex((item) => item.dataset.value === value);
        const currentIndex = enabledItems.findIndex(
            (item) => item.dataset.value === root.dataset.active,
        );

        if (linear && targetIndex > currentIndex + 1) {
            return;
        }

        activate(value);
    });

    root.addEventListener('keydown', (event) => {
        const trigger =
            event.target instanceof Element ? event.target.closest(TRIGGER_SELECTOR) : null;

        if (!(trigger instanceof HTMLButtonElement) || !root.contains(trigger)) {
            return;
        }

        const enabled = triggers();
        const index = enabled.indexOf(trigger);
        const orientation = root.dataset.orientation || 'horizontal';
        const nextKey = orientation === 'vertical' ? 'ArrowDown' : 'ArrowRight';
        const prevKey = orientation === 'vertical' ? 'ArrowUp' : 'ArrowLeft';

        let nextIndex = index;

        if (event.key === nextKey) {
            nextIndex = index + 1 >= enabled.length ? 0 : index + 1;
        } else if (event.key === prevKey) {
            nextIndex = index - 1 < 0 ? enabled.length - 1 : index - 1;
        } else if (event.key === 'Home') {
            nextIndex = 0;
        } else if (event.key === 'End') {
            nextIndex = enabled.length - 1;
        } else {
            return;
        }

        const nextTrigger = enabled[nextIndex];

        if (
            !(nextTrigger instanceof HTMLButtonElement) ||
            typeof nextTrigger.dataset.value !== 'string'
        ) {
            return;
        }

        if (linear) {
            const enabledItems = items();
            const currentIndex = enabledItems.findIndex(
                (item) => item.dataset.value === root.dataset.active,
            );
            const targetIndex = enabledItems.findIndex(
                (item) => item.dataset.value === nextTrigger.dataset.value,
            );

            if (targetIndex > currentIndex + 1) {
                event.preventDefault();
                return;
            }
        }

        event.preventDefault();
        activate(nextTrigger.dataset.value);
        nextTrigger.focus();
    });
}

document.addEventListener('stencil:mount', (event) => {
    if (!(event instanceof CustomEvent)) {
        return;
    }

    const mountRoot = event.detail?.root;

    if (!(mountRoot instanceof HTMLElement)) {
        return;
    }

    initSteppers(mountRoot);
});

if (typeof document !== 'undefined') {
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => initSteppers());
    } else {
        initSteppers();
    }
}
